from __future__ import annotations

import json
import os
import tempfile
import time
from contextlib import contextmanager

import fcntl

from app.config import CACHE_PATH, CACHE_TTL


def _cache_dir(path: str) -> str:
    return os.path.dirname(path) or "."


@contextmanager
def _exclusive_lock(path: str):
    """Serialize cache readers/writers across processes."""
    os.makedirs(_cache_dir(path), exist_ok=True)
    lock_path = f"{path}.lock"
    with open(lock_path, "a+", encoding="utf-8") as lock_file:
        fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)
        try:
            yield
        finally:
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)


def _read_cache(path: str) -> dict:
    try:
        with open(path, encoding="utf-8") as cache_file:
            data = json.load(cache_file)
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return {}
    return data if isinstance(data, dict) else {}


def _write_cache(path: str, data: dict) -> None:
    os.makedirs(_cache_dir(path), exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(prefix="profiles-", suffix=".json", dir=_cache_dir(path), text=True)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as tmp_file:
            json.dump(data, tmp_file, sort_keys=True, separators=(",", ":"))
            tmp_file.flush()
            os.fsync(tmp_file.fileno())
        os.replace(tmp_path, path)
    except Exception:
        try:
            os.unlink(tmp_path)
        except FileNotFoundError:
            pass
        raise


def get_or_load(key, loader, now=None):
    """Return a fresh cached JSON value, loading and persisting it on misses/expiry."""
    timestamp = time.time() if now is None else now
    key = str(key)

    with _exclusive_lock(CACHE_PATH):
        cache = _read_cache(CACHE_PATH)
        entry = cache.get(key)
        if isinstance(entry, dict) and "stored_at" in entry and "value" in entry:
            try:
                age = timestamp - float(entry["stored_at"])
            except (TypeError, ValueError):
                age = CACHE_TTL
            if age < CACHE_TTL:
                return entry["value"]

        value = loader()
        cache[key] = {"stored_at": timestamp, "value": value}
        _write_cache(CACHE_PATH, cache)
        return value
