from flask import request

from app.config import CACHE_TTL


def _is_profile_response() -> bool:
    return request.path.startswith("/api/accounts/") and request.path.endswith("/profile")


def apply_response_policy(response):
    """Mark successful public profile responses as reusable shared-cache content."""
    if response.status_code == 200 and _is_profile_response():
        response.headers["Cache-Control"] = f"public, max-age={CACHE_TTL}, s-maxage={CACHE_TTL}"
    return response
"}

