import json


def audit_log(logger, request, response):
    """Write one JSON log entry containing complete request and response bodies."""
    entry = {
        "method": request.method,
        "path": request.path,
        "request_body": request.get_data(as_text=True, cache=True),
        "response_body": response.get_data(as_text=True),
    }
    logger.info(json.dumps(entry, ensure_ascii=False, separators=(",", ":")))
"}

